PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?mother ?motherLabel ?deathPlace ?deathPlaceLabel WHERE {
  dbr:Princess_Maria_Maximilianovna_of_Leuchtenberg (dbo:mother|dbp:mother) ?mother .
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel)='en') }
  OPTIONAL {
    ?mother (dbo:deathPlace|dbp:deathPlace|dbp:placeOfDeath) ?deathPlace .
    OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER(lang(?deathPlaceLabel)='en') }
  }
}

